#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace StarterAssets.CQCEditorTools {
[InitializeOnLoad] public static class BuildChapelWorldMap {
const string Request="Assets/Editor/CQC/BuildChapelWorldMap-v1.request.txt";static double next;
static BuildChapelWorldMap(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;if(!File.Exists(Request)||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;try{Apply();AssetDatabase.DeleteAsset(Request);}catch(Exception e){File.WriteAllText("Logs/ChapelMap-error.txt",e.ToString());Debug.LogException(e);AssetDatabase.MoveAsset(Request,Request+".failed");}}
static void Apply(){var active=SceneManager.GetActiveScene();var main=SceneManager.GetSceneByPath("Assets/Scenes/MyForest.unity");bool opened=!main.isLoaded;if(opened)main=EditorSceneManager.OpenScene("Assets/Scenes/MyForest.unity",OpenSceneMode.Additive);GameObject cameraObject=null;RenderTexture target=null;Texture2D pixels=null;var previous=RenderTexture.active;bool fog=false;
try{SceneManager.SetActiveScene(main);fog=RenderSettings.fog;var roots=main.GetRootGameObjects();var portal=roots.SelectMany(g=>g.GetComponentsInChildren<ChapelThroneDomain>(true)).Single();var renderers=roots.Where(g=>g.name=="Castle Mountain"||g.name=="Lower Castle City").SelectMany(g=>g.GetComponentsInChildren<Renderer>()).Where(r=>r.bounds.size.x<2000&&r.bounds.size.z<2000).ToArray();if(renderers.Length==0)throw new InvalidOperationException("City bounds not found.");var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float side=Mathf.Max(bounds.size.x,bounds.size.z)+100;var center=bounds.center;
string backup="Assets/ForestExpansion/Backups/MyForest-before-world-map-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";if(!EditorSceneManager.SaveScene(main,backup,true))throw new IOException("Backup failed.");cameraObject=new GameObject("Temporary Map Capture");cameraObject.hideFlags=HideFlags.HideAndDontSave;var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.orthographicSize=side*.5f;camera.transform.SetPositionAndRotation(new Vector3(center.x,bounds.max.y+700,center.z),Quaternion.Euler(90,0,0));camera.nearClipPlane=.1f;camera.farClipPlane=2000;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.07f,.11f,.10f);camera.allowHDR=false;camera.allowMSAA=false;target=new RenderTexture(2048,2048,24,RenderTextureFormat.ARGB32);target.Create();camera.targetTexture=target;RenderSettings.fog=false;camera.Render();RenderTexture.active=target;pixels=new Texture2D(2048,2048,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,2048,2048),0,0);pixels.Apply();string folder="Assets/CityExpansion/WorldMap";Directory.CreateDirectory(folder);string path=folder+"/CastleCityMap.png";File.WriteAllBytes(path,pixels.EncodeToPNG());AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Default;importer.mipmapEnabled=false;importer.wrapMode=TextureWrapMode.Clamp;importer.maxTextureSize=2048;importer.SaveAndReimport();Undo.RecordObject(portal,"Add world map");portal.WorldMapTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);portal.MapWorldMin=new Vector2(center.x-side*.5f,center.z-side*.5f);portal.MapWorldMax=new Vector2(center.x+side*.5f,center.z+side*.5f);RenderSettings.fog=fog;EditorSceneManager.MarkSceneDirty(main);if(!EditorSceneManager.SaveScene(main))throw new IOException("Map scene save failed.");File.WriteAllText("Logs/ChapelMap-setup.txt","M opens world map. Right-hand selectable Throne Hall and Chapel Courtyard destinations. Teleport reuses same player, fade, input locking and safe arrival. Map bounds "+portal.MapWorldMin+" to "+portal.MapWorldMax+".\nTexture: "+path+"\nBackup: "+backup);File.WriteAllText("Assets/Editor/CQC/TestChapelMap-v1.request.txt","Test map open/close, pause, teleport into throne hall and return.");
}finally{RenderSettings.fog=fog;RenderTexture.active=previous;if(cameraObject)UnityEngine.Object.DestroyImmediate(cameraObject);if(target){target.Release();UnityEngine.Object.DestroyImmediate(target);}if(pixels)UnityEngine.Object.DestroyImmediate(pixels);if(active.IsValid()&&active.isLoaded)SceneManager.SetActiveScene(active);if(opened)EditorSceneManager.CloseScene(main,true);}}
}}
#endif
